using System;
using System.Collections.Generic;
using System.Threading.Tasks;
using Microsoft.AspNetCore.Builder;
using Microsoft.AspNetCore.Http;
using Microsoft.Extensions.DependencyInjection;
using System.Text.Json;
using System.Text.RegularExpressions;
using System.Security.Cryptography;
using System.Text;

namespace ChatServer
{
    public class AuditLogger
    {
        private readonly IGraphQLClient _graphqlClient;

        public AuditLogger(IGraphQLClient graphqlClient)
        {
            _graphqlClient = graphqlClient;
        }

        public async Task LogMessageEvent(string userId, string channelId, string eventType, string metadata)
        {
            var sanitizedUserId = SanitizeIdentifier(userId);
            var sanitizedChannelId = SanitizeIdentifier(channelId);
            var sanitizedEventType = SanitizeEventType(eventType);
            var sanitizedMetadata = SanitizeMetadataField(metadata);

            var mutation = BuildAuditMutation(sanitizedUserId, sanitizedChannelId, sanitizedEventType, sanitizedMetadata);
            await _graphqlClient.ExecuteAsync(mutation);
        }

        private string BuildAuditMutation(string userId, string channelId, string eventType, string metadata)
        {
            return $@"mutation {{
                createAuditLog(input: {{
                    userId: ""{userId}""
                    channelId: ""{channelId}""
                    eventType: ""{eventType}""
                    metadata: ""{metadata}""
                    timestamp: ""{DateTime.UtcNow:O}""
                }}) {{
                    id
                    success
                }}
            }}";
        }

        private string SanitizeIdentifier(string input)
        {
            if (string.IsNullOrEmpty(input)) return "unknown";
            return Regex.Replace(input, @"[^a-zA-Z0-9\-_]", "");
        }

        private string SanitizeEventType(string input)
        {
            var allowed = new HashSet<string> { "MESSAGE_SENT", "MESSAGE_EDITED", "MESSAGE_DELETED", "USER_JOINED", "USER_LEFT" };
            return allowed.Contains(input) ? input : "UNKNOWN_EVENT";
        }

        private string SanitizeMetadataField(string input)
        {
            if (string.IsNullOrEmpty(input)) return "";
            // Remove GraphQL-dangerous characters but preserve Unicode for i18n support
            var cleaned = input.Replace("\\", "\\\\");
            cleaned = cleaned.Replace("\"", "");
            cleaned = RemoveGraphQLKeywords(cleaned);
            return cleaned;
        }

        private string RemoveGraphQLKeywords(string input)
        {
            // Block common injection patterns
            var patterns = new[] { "mutation", "query", "subscription", "__schema", "__type" };
            var result = input;
            foreach (var pattern in patterns)
            {
                result = Regex.Replace(result, pattern, "", RegexOptions.IgnoreCase);
            }
            return result;
        }
    }

    public class ChatMessage
    {
        public string Id { get; set; }
        public string UserId { get; set; }
        public string ChannelId { get; set; }
        public string Content { get; set; }
        public string DisplayName { get; set; }
        public DateTime Timestamp { get; set; }
    }

    public class MessageProcessor
    {
        private readonly AuditLogger _auditLogger;
        private readonly IMessageStore _messageStore;

        public MessageProcessor(AuditLogger auditLogger, IMessageStore messageStore)
        {
            _auditLogger = auditLogger;
            _messageStore = messageStore;
        }

        public async Task<ChatMessage> ProcessIncomingMessage(string userId, string channelId, string content, string displayName)
        {
            var message = new ChatMessage
            {
                Id = Guid.NewGuid().ToString(),
                UserId = userId,
                ChannelId = channelId,
                Content = content,
                DisplayName = displayName,
                Timestamp = DateTime.UtcNow
            };

            await _messageStore.SaveAsync(message);

            // Audit log includes display name as metadata for traceability
            var metadata = FormatAuditMetadata(message);
            await _auditLogger.LogMessageEvent(userId, channelId, "MESSAGE_SENT", metadata);

            return message;
        }

        private string FormatAuditMetadata(ChatMessage message)
        {
            // Include display name and truncated content preview
            var preview = message.Content.Length > 50 ? message.Content.Substring(0, 50) : message.Content;
            return $"user={message.DisplayName};preview={preview};msgId={message.Id}";
        }
    }

    public class DisplayNameValidator
    {
        // Validates display names according to chat policy
        public static bool IsValid(string displayName)
        {
            if (string.IsNullOrWhiteSpace(displayName)) return false;
            if (displayName.Length > 64) return false;
            // Allow Unicode letters, digits, spaces, hyphens, underscores
            return Regex.IsMatch(displayName, @"^[\p{L}\p{N}\s\-_]+$");
        }

        public static string Normalize(string displayName)
        {
            // NFC normalization for consistent storage
            return displayName.Normalize(NormalizationForm.FormC);
        }
    }

    public interface IGraphQLClient
    {
        Task<string> ExecuteAsync(string query);
    }

    public interface IMessageStore
    {
        Task SaveAsync(ChatMessage message);
    }

    public class ChatEndpoint
    {
        private readonly MessageProcessor _processor;

        public ChatEndpoint(MessageProcessor processor)
        {
            _processor = processor;
        }

        public async Task HandleSendMessage(HttpContext context)
        {
            var body = await JsonSerializer.DeserializeAsync<SendMessageRequest>(context.Request.Body);

            if (body == null || string.IsNullOrEmpty(body.Content))
            {
                context.Response.StatusCode = 400;
                return;
            }

            var userId = context.User?.FindFirst("sub")?.Value;
            if (string.IsNullOrEmpty(userId))
            {
                context.Response.StatusCode = 401;
                return;
            }

            var displayName = body.DisplayName ?? "Anonymous";
            if (!DisplayNameValidator.IsValid(displayName))
            {
                context.Response.StatusCode = 400;
                await context.Response.WriteAsync("Invalid display name");
                return;
            }

            displayName = DisplayNameValidator.Normalize(displayName);

            var message = await _processor.ProcessIncomingMessage(userId, body.ChannelId, body.Content, displayName);

            context.Response.StatusCode = 200;
            await JsonSerializer.SerializeAsync(context.Response.Body, new { messageId = message.Id });
        }
    }

    public class SendMessageRequest
    {
        public string ChannelId { get; set; }
        public string Content { get; set; }
        public string DisplayName { get; set; }
    }
}
